package com.fixmer.mared;
import com.fixmer.genesis.technology.server.remote.*;import com.fixmer.genesis.technology.server.firstlaunch.*;import java.nio.file.*;import java.util.*;
/** Actual HMAC/nonce/identity/freshness checks, no Minecraft user or online service instantiated. */
public final class SessionHandoffChecks89 {
 static int n;static void ok(boolean v){if(!v)throw new AssertionError("session89 "+n);n++;}interface W{void run()throws Exception;}static void reject(W w)throws Exception{try{w.run();}catch(Exception e){n++;return;}throw new AssertionError("accepted invalid handoff "+n);}
 public static void main(String[] args)throws Exception{Path r=Files.createTempDirectory("genesis-session89-");try{byte[] key=new byte[32];new java.security.SecureRandom().nextBytes(key);Files.write(r.resolve("channel.key"),key);long now=System.currentTimeMillis();Map<String,String> ctx=Map.of("sourceRun",UUID.randomUUID().toString(),"profile",r.toString(),"account",UUID.randomUUID().toString(),"mode","ONLINE","scope","INITIAL","pid","123","birth","123456");var req=new TreeMap<>(ctx);req.putAll(Map.of("schema","89","request",UUID.randomUUID().toString(),"nonce",UUID.randomUUID().toString(),"issued",Long.toString(now)));Path f=r.resolve("auth89.request");Files.write(f,LocalApply67.sign(key,req));ok(SessionHandoff89.request(r,ctx,now).equals(req));reject(()->SessionHandoff89.request(r,ctx,now+10001));reject(()->SessionHandoff89.request(r,ctx,now-1));
 for(String k:SessionHandoff89.CONTEXT){var changed=new TreeMap<>(ctx);changed.put(k,"wrong");reject(()->SessionHandoff89.request(r,changed,now));}
 Map<String,String> user=Map.of("account",ctx.get("account"),"name","TestPlayer","accessToken","private-fixture89","userType","msa");SessionHandoff89.answer(r,req,user,now);var response=LocalApply67.verify(key,Files.readAllBytes(r.resolve("auth89.response")));ok(response.get("nonce").equals(req.get("nonce")));ok(response.get("request").equals(req.get("request")));ok(response.get("accessToken").equals("private-fixture89"));ok(response.get("answered").equals(Long.toString(now)));
 var other=new TreeMap<>(user);other.put("account",UUID.randomUUID().toString());SessionHandoff89.answer(r,req,other,now);var denied=LocalApply67.verify(key,Files.readAllBytes(r.resolve("auth89.response")));ok(denied.get("error").equals("AUTH89_ACCOUNT_CHANGED"));ok(!denied.containsKey("accessToken"));other.put("account",ctx.get("account"));other.put("accessToken","bad\ntoken");SessionHandoff89.answer(r,req,other,now);ok(LocalApply67.verify(key,Files.readAllBytes(r.resolve("auth89.response"))).get("error").equals("AUTH89_SESSION"));reject(()->SessionHandoff89.answer(r,req,user,now+10001));
 Files.writeString(f,"TAMPER");reject(()->SessionHandoff89.request(r,ctx,now));var wrong=new TreeMap<>(req);wrong.put("nonce",new UUID(0,0).toString());Files.write(f,LocalApply67.sign(key,wrong));reject(()->SessionHandoff89.request(r,ctx,now));wrong=new TreeMap<>(req);wrong.put("account",new UUID(0,0).toString());Files.write(f,LocalApply67.sign(key,wrong));var offline=new TreeMap<>(ctx);offline.put("account",new UUID(0,0).toString());offline.put("mode","LOCAL_OFFLINE");wrong.put("mode","LOCAL_OFFLINE");Files.write(f,LocalApply67.sign(key,wrong));ok(!SessionHandoff89.request(r,offline,now).isEmpty());
 Files.delete(f);ok(SessionHandoff89.request(r,ctx,now).isEmpty());System.out.println("Session89 actual HMAC/context/account/nonce/freshness checks passed: "+n+"; no Minecraft or network service.");
 }finally{try(var paths=Files.walk(r)){for(Path p:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}}
}
